INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Drucker Funktion, Einsatz, Varianten > Tintenstrahldrucker (Inkjet)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Tintenstrahldrucker unabhängig von der Tintenkompatibilität ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Drucker benötigen spezifische Tintenpatronen"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität verhindert Druck"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl eines Tintenstrahldruckers immer die Druckqualitätsanforderungen berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Qualität entscheidet über Einsatz"}, {"text": "Nein", "correct": false, "because": "Anforderungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Druckgeschwindigkeit eines Tintenstrahldruckers für alle Anwendungen irrelevant?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit wichtig bei hohem Volumen"}, {"text": "Ja", "correct": false, "because": "Beeinflusst Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Tintenstrahldrucker ohne Rücksicht auf die Papiertypen ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Papier beeinflusst Druckqualität"}, {"text": "Ja", "correct": false, "because": "Papiertyp ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Tintenstrahldrucker immer günstiger als Laserdrucker?', 2, '[{"text": "Ja", "correct": true, "because": "Anschaffungskosten meist niedriger"}, {"text": "Nein", "correct": false, "because": "Preisunterschied ist üblich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl eines Tintenstrahldruckers am wichtigsten?', 3, '[{"text": "Druckanforderungen", "correct": true, "because": "Bestimmen Qualität und Einsatz"}, {"text": "Marke", "correct": false, "because": "Sekundär"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle wird für moderne Tintenstrahldrucker am häufigsten verwendet?', 2, '[{"text": "USB", "correct": true, "because": "Universeller Standard"}, {"text": "Parallelport", "correct": false, "because": "Veraltet"}, {"text": "Serial", "correct": false, "because": "Weniger gebräuchlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verbrauchsmaterial ist für Tintenstrahldrucker essenziell?', 2, '[{"text": "Tintenpatronen", "correct": true, "because": "Übertragen Tinte aufs Papier"}, {"text": "Toner", "correct": false, "because": "Für Laserdrucker"}, {"text": "Farbbänder", "correct": false, "because": "Für Matrixdrucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendung ist typisch für Tintenstrahldrucker?', 3, '[{"text": "Fotodruck", "correct": true, "because": "Hohe Farbqualität"}, {"text": "Durchschlagdruck", "correct": false, "because": "Falsche Technologie"}, {"text": "Massentextdruck", "correct": false, "because": "Laserdrucker besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von Tintenstrahldruckern?', 2, '[{"text": "Hohe Druckqualität bei Fotos", "correct": true, "because": "Gute Farbwiedergabe"}, {"text": "Hohe Druckgeschwindigkeit", "correct": false, "because": "Langsamer als Laser"}, {"text": "Geringe Betriebskosten", "correct": false, "because": "Tinte oft teuer"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl eines Tintenstrahldruckers?', 4, '[{"text": "Druckqualität", "correct": true, "because": "Bestimmt Bild- und Textwiedergabe"}, {"text": "Papiertypen", "correct": true, "because": "Beeinflussen Ergebnis"}, {"text": "Druckvolumen", "correct": true, "because": "Bestimmt Eignung"}, {"text": "Gewicht des Druckers", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Tintenstrahldrucker?', 3, '[{"text": "Hohe Farbqualität", "correct": true, "because": "Für Fotos geeignet"}, {"text": "Geringere Anschaffungskosten", "correct": true, "because": "Günstiger als Laser"}, {"text": "Vielseitigkeit", "correct": true, "because": "Verschiedene Papiertypen"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Langsamer als Laser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl eines Tintenstrahldruckers auftreten?', 3, '[{"text": "Hohe Tintenkosten", "correct": true, "because": "Betriebskosten steigen"}, {"text": "Langsame Druckgeschwindigkeit", "correct": true, "because": "Bei hohem Volumen"}, {"text": "Trocknen der Tinte", "correct": true, "because": "Bei seltenem Gebrauch"}, {"text": "Falsche Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen können Tintenstrahldrucker unterstützen?', 4, '[{"text": "USB", "correct": true, "because": "Standardverbindung"}, {"text": "Wi-Fi", "correct": true, "because": "Drahtlose Option"}, {"text": "Ethernet", "correct": true, "because": "Für Netzwerk"}, {"text": "HDMI", "correct": false, "because": "Für Video, nicht Drucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen profitieren von Tintenstrahldruckern?', 3, '[{"text": "Fotodruck", "correct": true, "because": "Hohe Farbgenauigkeit"}, {"text": "Grafikdesign", "correct": true, "because": "Detailreiche Ausgabe"}, {"text": "Heimgebrauch", "correct": true, "because": "Vielseitig und günstig"}, {"text": "Massendruck", "correct": false, "because": "Laserdrucker besser"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Tintenstrahldrucker verwenden Tintenpatronen. b) Sie sind schneller als Laserdrucker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tinten ja, langsamer als Laser"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Tintenstrahldrucker bieten hohe Druckqualität bei Fotos. b) Sie sind für Massendruck ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fotos ja, Massendruck nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Tintenstrahldrucker können verschiedene Papiertypen bedrucken. b) Ihre Betriebskosten sind immer niedriger als bei Laserdruckern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Papiertypen ja, Kosten oft höher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Tintenstrahldrucker sind günstiger in der Anschaffung als Laserdrucker. b) Sie trocknen bei seltenem Gebrauch nicht aus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anschaffung ja, Tinte trocknet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Tintenstrahldrucker unterstützen Wi-Fi-Druck. b) Sie sind für technische Zeichnungen besser als Plotter.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wi-Fi ja, Plotter besser für Zeichnungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

